// Package fishtoken is the unreleased GnoFish FISH ledger.
// Init mints a fixed supply once. No later call can mint.
// While transfers are closed, a normal wallet cannot send FISH, so it cannot
// fund a pool or sell through a market. The deploy wallet opens transfers.
// The five treasury wallets, the deploy wallet, and a reward realm the deploy
// wallet has granted may still send. This realm has no pool and no trade.
// Public-sale FISH is minted to the deploy wallet. fishtoken-1.
package fishtoken

import (
	"chain"
	"chain/runtime/unsafe"
	"strconv"

	"gno.land/p/nt/grc20/v0"
	"gno.land/p/nt/seqid/v0"
)

const (
	unit            int64 = 1_000_000
	supplyWhole     int64 = 100_000_000
	seasonWhole     int64 = 43_000_000
	liquidityWhole  int64 = 20_000_000
	ecosystemWhole  int64 = 15_000_000
	communityWhole  int64 = 12_000_000
	teamWhole       int64 = 5_000_000
	saleWhole       int64 = 5_000_000
)

var (
	seasonAddr    = address("g1m6z3l9q577dltj73ym8fu0068peupqg468r5xe")
	liquidityAddr = address("g1lepzz7lehwfnwng0ddxaglz2kzmsf6pyy5f6tw")
	ecosystemAddr = address("g1p4cylgemajmw93e9a0nr0fmph60gee2yhkn2kz")
	communityAddr = address("g1dpklfykp2mrhcwccek54scv43kamtxlszya2z8")
	teamAddr      = address("g15ejerz2n0xn5x94zezhquvwvp98m3jgkcwdrya")
)

var (
	token     *grc20.Token
	ledger    *grc20.PrivateLedger
	seq       seqid.ID
	inited    bool
	open      bool
	admin     address
	mover     map[address]bool
	payer     map[address]bool
)

// Init mints the fixed supply once. The caller is the deploy wallet and receives the public-sale FISH. No coins.
func Init(cur realm) {
	caller := requireUser(cur)
	takeExact(0)
	if inited {
		panic("fishtoken: init")
	}
	if !distinct(caller, seasonAddr, liquidityAddr, ecosystemAddr, communityAddr, teamAddr) {
		panic("fishtoken: addr")
	}
	tok, led := grc20.NewToken("FISH", "FISH", 6, seq.Next(), cur)
	credit(led, seasonAddr, seasonWhole*unit)
	credit(led, liquidityAddr, liquidityWhole*unit)
	credit(led, ecosystemAddr, ecosystemWhole*unit)
	credit(led, communityAddr, communityWhole*unit)
	credit(led, teamAddr, teamWhole*unit)
	credit(led, caller, saleWhole*unit)
	if tok.TotalSupply() != supplyWhole*unit {
		panic("fishtoken: supply")
	}
	token = tok
	ledger = led
	admin = caller
	open = false
	mover = map[address]bool{
		caller:        true,
		seasonAddr:    true,
		liquidityAddr: true,
		ecosystemAddr: true,
		communityAddr: true,
		teamAddr:      true,
	}
	payer = map[address]bool{}
	inited = true
	chain.Emit("Init", "admin", caller.String(), "supply", strconv.FormatInt(supplyWhole*unit, 10))
}

// SetTransfers opens or closes ordinary wallet sends. The deploy wallet only. No coins.
func SetTransfers(cur realm, next bool) {
	caller := requireUser(cur)
	takeExact(0)
	requireReady()
	requireAdmin(caller)
	open = next
	chain.Emit("SetTransfers", "open", strconv.FormatBool(next))
}

// GrantMover lets that wallet send FISH while transfers are closed. The deploy wallet only. No coins.
func GrantMover(cur realm, who address) {
	caller := requireUser(cur)
	takeExact(0)
	requireReady()
	requireAdmin(caller)
	if !who.IsValid() {
		panic("fishtoken: addr")
	}
	mover[who] = true
	chain.Emit("GrantMover", "who", who.String())
}

// RevokeMover removes that wallet from the closed-transfer list. The deploy wallet only. No coins.
func RevokeMover(cur realm, who address) {
	caller := requireUser(cur)
	takeExact(0)
	requireReady()
	requireAdmin(caller)
	if !who.IsValid() {
		panic("fishtoken: addr")
	}
	delete(mover, who)
	chain.Emit("RevokeMover", "who", who.String())
}

// GrantDistributor lets that realm pay FISH to users while transfers are closed. The deploy wallet only. No coins.
func GrantDistributor(cur realm, who address) {
	caller := requireUser(cur)
	takeExact(0)
	requireReady()
	requireAdmin(caller)
	if !who.IsValid() {
		panic("fishtoken: addr")
	}
	payer[who] = true
	chain.Emit("GrantDistributor", "who", who.String())
}

// RevokeDistributor removes that reward realm. The deploy wallet only. No coins.
func RevokeDistributor(cur realm, who address) {
	caller := requireUser(cur)
	takeExact(0)
	requireReady()
	requireAdmin(caller)
	if !who.IsValid() {
		panic("fishtoken: addr")
	}
	delete(payer, who)
	chain.Emit("RevokeDistributor", "who", who.String())
}

// TransferAdmin hands the switch to next. Balances stay where they are. No coins.
func TransferAdmin(cur realm, next address) {
	caller := requireUser(cur)
	takeExact(0)
	requireReady()
	requireAdmin(caller)
	if !next.IsValid() {
		panic("fishtoken: admin")
	}
	admin = next
	mover[next] = true
	chain.Emit("TransferAdmin", "next", next.String())
}

// Transfer sends FISH from the caller to to.
// A closed ledger rejects an ordinary wallet. Listed wallets and granted reward realms may still send.
func Transfer(cur realm, to address, amount int64) {
	caller := cur.Previous().Address()
	if cur.Previous().IsUserCall() {
		takeExact(0)
	}
	requireReady()
	requireAmount(amount, to)
	if !mayMove(cur, caller, caller) {
		panic("fishtoken: closed")
	}
	must(ledger.CallerTeller().Transfer(0, cur, to, amount))
	chain.Emit("Send", "to", to.String(), "amount", strconv.FormatInt(amount, 10))
}

// Approve sets the spender allowance. It does not move FISH and does not open trading. No coins from an EOA.
func Approve(cur realm, spender address, amount int64) {
	if cur.Previous().IsUserCall() {
		takeExact(0)
	} else if !payer[cur.Previous().Address()] {
		panic("fishtoken: closed")
	}
	requireReady()
	if amount < 0 || !spender.IsValid() {
		panic("fishtoken: amount")
	}
	must(ledger.CallerTeller().Approve(0, cur, spender, amount))
	chain.Emit("Approve", "spender", spender.String(), "amount", strconv.FormatInt(amount, 10))
}

// TransferFrom sends FISH using the caller's allowance.
// While closed, only a granted reward realm may pull, and only from its own balance or from a listed wallet.
func TransferFrom(cur realm, owner, to address, amount int64) {
	caller := cur.Previous().Address()
	if cur.Previous().IsUserCall() {
		takeExact(0)
	}
	requireReady()
	requireAmount(amount, to)
	if !mayMove(cur, caller, owner) {
		panic("fishtoken: closed")
	}
	must(ledger.CallerTeller().TransferFrom(0, cur, owner, to, amount))
	chain.Emit("SendFrom", "owner", owner.String(), "to", to.String(), "amount", strconv.FormatInt(amount, 10))
}

func TransfersOpen() bool { return open }
func IsMover(who address) bool {
	return mover[who]
}
func IsDistributor(who address) bool { return payer[who] }
func Version() string                { return "fishtoken-1" }
func Admin() address                 { return admin }

func Name() string {
	requireReady()
	return token.GetName()
}

func Symbol() string {
	requireReady()
	return token.GetSymbol()
}

func Decimals() int {
	requireReady()
	return token.GetDecimals()
}

func TotalSupply() int64 {
	requireReady()
	return token.TotalSupply()
}

func BalanceOf(who address) int64 {
	requireReady()
	return token.BalanceOf(who)
}

func Allowance(owner, spender address) int64 {
	requireReady()
	return token.Allowance(owner, spender)
}

func TokenID() string {
	requireReady()
	return token.ID()
}

func Render(path string) string {
	if path != "" {
		return "# FISH\n\nUnknown path.\n"
	}
	if !inited {
		return "# FISH\n\nNot opened.\n"
	}
	state := "closed"
	if open {
		state = "open"
	}
	return "# FISH\n\nFixed supply. Transfers are " + state + ". A closed ledger does not fund a pool and does not trade. Listed wallets and granted reward realms can still send. Public-sale FISH was minted to the deploy wallet.\n"
}

func mayMove(cur realm, caller, from address) bool {
	if open {
		return true
	}
	if cur.Previous().IsUserCall() {
		return from == caller && mover[caller]
	}
	if !payer[caller] {
		return false
	}
	return from == caller || mover[from]
}

func requireAdmin(caller address) {
	if caller != admin {
		panic("fishtoken: admin")
	}
}

func requireAmount(amount int64, to address) {
	if amount <= 0 || !to.IsValid() {
		panic("fishtoken: amount")
	}
}

func credit(led *grc20.PrivateLedger, who address, amount int64) {
	if err := led.Mint(who, amount); err != nil {
		panic(err)
	}
}

func must(err error) {
	if err != nil {
		panic(err)
	}
}

func requireReady() {
	if !inited || token == nil || ledger == nil {
		panic("fishtoken: init")
	}
}

func requireUser(cur realm) address {
	if !cur.Previous().IsUserCall() {
		panic("fishtoken: eoa")
	}
	return cur.Previous().Address()
}

func takeExact(n int64) {
	sent := unsafe.OriginSend()
	if n == 0 {
		if len(sent) != 0 {
			panic("fishtoken: payment")
		}
		return
	}
	panic("fishtoken: payment")
}

func distinct(xs ...address) bool {
	for i, a := range xs {
		if !a.IsValid() {
			return false
		}
		for j := 0; j < i; j++ {
			if xs[j] == a {
				return false
			}
		}
	}
	return true
}

// Package fishseason is the Season 1 paying board.
// The open is 2026-10-16 00:00:00 UTC. The deploy wallet sets the end, posts
// up to 20 winners, and seals the board. Pay then pulls FISH from the season
// wallet to those addresses. This realm does not watch the sea and does not
// treat a fishlive Settle as a win. fishlive is not called.
// The stage script rewrites the fishtoken import to the deploy wallet's package.
// A kill still pays no FISH by itself. fishseason-1.
package fishseason

import (
	"chain"
	"chain/runtime/unsafe"
	"strconv"
	"time"

	fish "gno.land/r/g1n4pl5uc4yt5r96m9w6fmdznx3x0jyg8l6arhmt/fishtoken"
)

const (
	unit      int64 = 1_000_000
	places          = 20
	startUnix int64 = 1_792_108_800
)

var seasonAddr = address("g1m6z3l9q577dltj73ym8fu0068peupqg468r5xe")

// Whole FISH for places 1 through 20. The sum is 100,000.
var prizeWhole = [places]int64{
	16_000, 12_500, 10_000, 8_000, 7_000,
	6_000, 5_500, 5_000, 4_500, 4_000,
	3_500, 3_000, 2_800, 2_500, 2_200,
	2_000, 1_800, 1_500, 1_200, 1_000,
}

var (
	inited  bool
	admin   address
	self    address
	endUnix int64
	sealed bool
	winner [places]address
	paid   [places]bool
)

// clockUnix stays 0 on chain. The test in this package sets it. No call writes it.
var clockUnix int64

// Init records the deploy wallet as admin. It does not move FISH. No coins.
func Init(cur realm) {
	caller := requireUser(cur)
	takeExact(0)
	if inited {
		panic("fishseason: init")
	}
	admin = caller
	self = cur.Address()
	inited = true
	chain.Emit("Init", "admin", admin.String())
}

// SetEnd stores the close, as Unix seconds. The deploy wallet only, and only before seal. No coins.
func SetEnd(cur realm, unix int64) {
	caller := requireUser(cur)
	takeExact(0)
	requireReady()
	requireAdmin(caller)
	if sealed || unix <= startUnix {
		panic("fishseason: end")
	}
	endUnix = unix
	chain.Emit("End", "unix", strconv.FormatInt(unix, 10))
}

// SetPlace posts one winner. Places are 1 through 20. The same address cannot take two places. No coins.
func SetPlace(cur realm, place int, who address) {
	caller := requireUser(cur)
	takeExact(0)
	requireReady()
	requireAdmin(caller)
	if sealed {
		panic("fishseason: seal")
	}
	slot := slotOf(place)
	if !who.IsValid() || who == seasonAddr || who == cur.Address() {
		panic("fishseason: addr")
	}
	for i := 0; i < places; i++ {
		if i != slot && winner[i] == who {
			panic("fishseason: dup")
		}
	}
	winner[slot] = who
	chain.Emit("Place", "place", strconv.Itoa(place), "who", who.String())
}

// ClearPlace removes one unsealed place. No coins.
func ClearPlace(cur realm, place int) {
	caller := requireUser(cur)
	takeExact(0)
	requireReady()
	requireAdmin(caller)
	if sealed {
		panic("fishseason: seal")
	}
	winner[slotOf(place)] = address("")
	chain.Emit("Clear", "place", strconv.Itoa(place))
}

// Seal freezes the end and the places. At least one place must be posted. No coins.
func Seal(cur realm) {
	caller := requireUser(cur)
	takeExact(0)
	requireReady()
	requireAdmin(caller)
	if sealed || endUnix == 0 || filled() < 1 {
		panic("fishseason: seal")
	}
	sealed = true
	chain.Emit("Seal", "end", strconv.FormatInt(endUnix, 10))
}

// Pay sends each unpaid posted prize from the season wallet to that winner.
// The board must be sealed and the close must have passed. No coins.
// fishtoken must list this realm as a distributor, and the season wallet must
// have approved this realm for the FISH. A second pay of the same place does nothing.
func Pay(cur realm) {
	requireUser(cur)
	takeExact(0)
	requireReady()
	if !sealed {
		panic("fishseason: seal")
	}
	if nowUnix() < endUnix {
		panic("fishseason: early")
	}
	due := Due()
	if due == 0 {
		panic("fishseason: paid")
	}
	if !fish.IsDistributor(cur.Address()) {
		panic("fishseason: grant")
	}
	if fish.Allowance(seasonAddr, cur.Address()) < due {
		panic("fishseason: allowance")
	}
	n := 0
	for i := 0; i < places; i++ {
		if paid[i] || !winner[i].IsValid() {
			continue
		}
		who := winner[i]
		amt := prizeWhole[i] * unit
		paid[i] = true
		n++
		fish.TransferFrom(cross(cur), seasonAddr, who, amt)
		chain.Emit("Pay", "place", strconv.Itoa(i+1), "who", who.String(), "amount", strconv.FormatInt(amt, 10))
	}
	if n == 0 {
		panic("fishseason: paid")
	}
}

// TransferAdmin hands the board to next. Posted places stay. No coins.
func TransferAdmin(cur realm, next address) {
	caller := requireUser(cur)
	takeExact(0)
	requireReady()
	requireAdmin(caller)
	if !next.IsValid() || next == admin {
		panic("fishseason: admin")
	}
	admin = next
	chain.Emit("Admin", "next", next.String())
}

func Version() string { return "fishseason-1" }

func Admin() address { return admin }

func Realm() address { return self }

func Start() int64 { return startUnix }

func End() int64 { return endUnix }

func Sealed() bool { return sealed }

func SeasonWallet() address { return seasonAddr }

func PlaceOf(place int) address { return winner[slotOf(place)] }

func PrizeOf(place int) int64 { return prizeWhole[slotOf(place)] * unit }

func PaidOf(place int) bool { return paid[slotOf(place)] }

func Due() int64 {
	var sum int64
	for i := 0; i < places; i++ {
		if !paid[i] && winner[i].IsValid() {
			sum += prizeWhole[i] * unit
		}
	}
	return sum
}

func Render(path string) string {
	if path != "" {
		return "# Season 1\n\nUnknown path.\n"
	}
	if !inited {
		return "# Season 1\n\nNot opened.\n"
	}
	state := "open"
	if sealed {
		state = "sealed"
	}
	return "# Season 1\n\nStart " + strconv.FormatInt(startUnix, 10) +
		". End " + strconv.FormatInt(endUnix, 10) +
		". Board " + state +
		". Due " + strconv.FormatInt(Due(), 10) + " base units.\n"
}

func nowUnix() int64 {
	if clockUnix != 0 {
		return clockUnix
	}
	return time.Now().Unix()
}

func slotOf(place int) int {
	if place < 1 || place > places {
		panic("fishseason: place")
	}
	return place - 1
}

func filled() int {
	n := 0
	for i := 0; i < places; i++ {
		if winner[i].IsValid() {
			n++
		}
	}
	return n
}

func requireReady() {
	if !inited {
		panic("fishseason: init")
	}
}

func requireAdmin(caller address) {
	if caller != admin {
		panic("fishseason: admin")
	}
}

func requireUser(cur realm) address {
	if !cur.Previous().IsUserCall() {
		panic("fishseason: eoa")
	}
	return cur.Previous().Address()
}

func takeExact(n int64) {
	sent := unsafe.OriginSend()
	if n == 0 {
		if len(sent) != 0 {
			panic("fishseason: payment")
		}
		return
	}
	panic("fishseason: payment")
}

// Package gnofish is the GnoFish sale NFT.
// A listed wallet mints for free. Anyone else pays exactly 100 GNOT.
// An address may mint as many times as the 10000 cap allows.
// The portrait is rolled in the same call. Every NFT is owned by the admin.
// The whole 100 GNOT is sent to that admin. This realm does not add FISH liquidity.
// The height and the next id are public before the transaction, so the roll can be predicted. This is not drand.
// Adena reads OwnerOf, BalanceOf, TokenURI (the https image) and TokenMetadata
// (JSON, traitType). NewToken and Transfer come from the GRC721 ledger.
// This package does not swim, settle, or draw FISH. fishlive stays untouched.
// Nomaq lists with List, UpdatePrice, Cancel, and Buy. ItemLine and ListOpen feed the page.
// gnofish-1.
package gnofish

import (
	"chain"
	"chain/banker"
	"chain/runtime"
	"chain/runtime/unsafe"
	"crypto/sha256"
	"errors"
	"strconv"

	"gno.land/p/nt/grc721/enumerable/v0"
	"gno.land/p/nt/grc721/v0"
	"gno.land/p/nt/seqid/v0"
)

const (
	denom            = "ugnot"
	mintPrice  int64 = 100_000_000
	maxAsk     int64 = 100_000_000_000_000
	maxMint          = 10_000
	listCap          = 50
	slug             = "gnofish"
	imageIPFS        = "ipfs://bafybeifdmgbtq3nf7xuepvygotk6ulk4wo7xshsi2yr4xukglsdpzz7p2i/"
	imageHTTPS       = "https://gateway.pinata.cloud/ipfs/bafybeifdmgbtq3nf7xuepvygotk6ulk4wo7xshsi2yr4xukglsdpzz7p2i/"
)

var (
	species  = [6]string{"Bubble", "Tideblade", "Abysswing", "Embermaw", "Aurelion", "Astravex"}
	rarities = [6]string{"common", "uncommon", "rare", "epic", "legendary", "mythic"}
	portrait = [6]string{"common-fish.jpg", "uncommon-fish.jpg", "race-fish.jpg", "epic-fish.jpg", "legendary-fish.jpg", "mythic-fish.jpg"}
	traits   = [3]string{"swift", "fang", "hide"}
	biteBase = [6]int{24, 30, 37, 45, 54, 66}
	hpBase   = [6]int{100, 122, 148, 178, 214, 256}
	spdBase  = [6]int{108, 104, 100, 96, 92, 88}
)

type fish struct {
	owner    address
	payer    address
	name     string
	rarity   string
	trait    string
	file     string
	bite     int
	hp       int
	speed    int
	height   int64
	revealed bool
	seller   address
	ask      int64
	onSale   bool
}

var (
	inited bool
	self   address
	admin  address
	minted int
	roster []fish
	listed map[address]bool
	token   *grc721.Token
	ledger  *grc721.PrivateLedger
	teller  grc721.Teller
	indexed *enumerable.Enumerable
	seq     seqid.ID
)

// Init opens the sale. The caller becomes the admin and the owner of every mint. No coins.
func Init(cur realm) {
	if !cur.Previous().IsUserCall() {
		panic("fishdrop: eoa")
	}
	takeExact(0)
	if inited {
		panic("fishdrop: init")
	}
	inited = true
	self = cur.Address()
	admin = cur.Previous().Address()
	listed = map[address]bool{}
	roster = []fish{{}}
	tok, led := grc721.NewToken("GnoFish", "GFISH", seq.Next(), cur)
	token = tok
	ledger = led
	teller = led.CallerTeller()
	indexed, _ = enumerable.NewEnumerable(led)
	chain.Emit("Init", "admin", admin.String())
}

// Grant lets that wallet mint without paying. Admin only. There is no per-address cap.
func Grant(cur realm, who address) {
	adminOnly(cur)
	if !who.IsValid() {
		panic("fishdrop: addr")
	}
	listed[who] = true
	chain.Emit("Grant", "who", who.String())
}

// Revoke removes the free mint.
func Revoke(cur realm, who address) {
	adminOnly(cur)
	if !who.IsValid() {
		panic("fishdrop: addr")
	}
	listed[who] = false
	chain.Emit("Revoke", "who", who.String())
}

// TransferAdmin moves the wallet that receives NFTs and GNOT.
func TransferAdmin(cur realm, next address) {
	adminOnly(cur)
	if !next.IsValid() || next == admin {
		panic("fishdrop: addr")
	}
	admin = next
	chain.Emit("Admin", "who", next.String())
}

// Mint rolls one fish and gives it to the admin. A listed wallet sends nothing. Everyone else sends 100 GNOT, and that full amount goes to the admin.
func Mint(cur realm) int {
	if !cur.Previous().IsUserCall() {
		panic("fishdrop: eoa")
	}
	if !inited {
		panic("fishdrop: init")
	}
	caller := cur.Previous().Address()
	free := listed[caller]
	if free {
		takeExact(0)
	} else {
		takeExact(mintPrice)
	}
	if minted >= maxMint {
		panic("fishdrop: mint")
	}
	height := runtime.ChainHeight()
	if height < 1 {
		panic("fishdrop: mint")
	}
	id := grow()
	row := &roster[id]
	rarity, trait, bite, hp, speed, tier := Roll(caller, height, id)
	row.owner = admin
	row.payer = caller
	row.rarity = rarity
	row.trait = trait
	row.bite = bite
	row.hp = hp
	row.speed = speed
	row.height = height
	row.name = pickName(tier)
	row.file = portrait[tier]
	row.revealed = true
	if err := ledger.Mint(admin, grc721.TokenID(strconv.Itoa(id))); err != nil {
		panic("fishdrop: mint")
	}
	if !free {
		send(admin, mintPrice, cur)
	}
	chain.Emit("Mint", "id", strconv.Itoa(id), "payer", caller.String(), "owner", admin.String(), "rarity", rarity, "file", row.file)
	return id
}

// Transfer moves a fish the caller owns. The call sends no coins.
func Transfer(cur realm, to address, id int) {
	from := gate(cur)
	move(cur, from, to, id)
}

// TransferFrom moves a fish. The caller must own it or be approved for it.
func TransferFrom(cur realm, from, to address, id int) {
	gate(cur)
	move(cur, from, to, id)
}

// Approve lets to move this fish once. The caller must own it.
func Approve(cur realm, to address, id int) {
	gate(cur)
	if err := teller.Approve(0, cur, to, tidOf(id)); err != nil {
		panic("fishdrop: approve")
	}
}

// SetApprovalForAll lets operator move every fish of the caller, or revokes it.
func SetApprovalForAll(cur realm, operator address, approved bool) {
	gate(cur)
	if err := teller.SetApprovalForAll(0, cur, operator, approved); err != nil {
		panic("fishdrop: approve")
	}
}

// List escrows the fish to this realm and puts it on sale. The caller sends no coins.
func List(cur realm, id int, priceUgnot int64) {
	caller := gate(cur)
	row := must(id)
	if priceUgnot <= 0 || priceUgnot > maxAsk || !row.revealed || row.onSale || row.owner != caller {
		panic("fishdrop: list")
	}
	ledgerMove(caller, caller, self, id)
	row.onSale = true
	row.seller = caller
	row.ask = priceUgnot
	row.owner = self
	chain.Emit("List", "id", strconv.Itoa(id), "seller", caller.String(), "price", strconv.FormatInt(priceUgnot, 10))
}

// UpdatePrice changes the ask of a fish the caller is selling.
func UpdatePrice(cur realm, id int, priceUgnot int64) {
	caller := gate(cur)
	row := must(id)
	if priceUgnot <= 0 || priceUgnot > maxAsk || !row.onSale || row.seller != caller {
		panic("fishdrop: list")
	}
	row.ask = priceUgnot
	chain.Emit("List", "id", strconv.Itoa(id), "seller", caller.String(), "price", strconv.FormatInt(priceUgnot, 10))
}

// Cancel returns a listed fish to its seller. The call sends no coins.
func Cancel(cur realm, id int) {
	caller := gate(cur)
	row := must(id)
	if !row.onSale || row.seller != caller {
		panic("fishdrop: list")
	}
	ledgerMove(self, self, caller, id)
	row.onSale = false
	row.owner = caller
	row.seller = address("")
	row.ask = 0
	chain.Emit("Cancel", "id", strconv.Itoa(id))
}

// Buy pays the ask, in full, to the seller and gives the fish to the buyer.
func Buy(cur realm, id int) {
	if !cur.Previous().IsUserCall() {
		panic("fishdrop: eoa")
	}
	if !inited {
		panic("fishdrop: init")
	}
	row := must(id)
	buyer := cur.Previous().Address()
	if !row.onSale || buyer == row.seller {
		panic("fishdrop: list")
	}
	price := row.ask
	seller := row.seller
	takeExact(price)
	ledgerMove(self, self, buyer, id)
	row.onSale = false
	row.owner = buyer
	row.seller = address("")
	row.ask = 0
	send(seller, price, cur)
	chain.Emit("Buy", "id", strconv.Itoa(id), "buyer", buyer.String(), "price", strconv.FormatInt(price, 10))
}

